def grp(order):
    out=[]
    for t in itertools.product("ACGT", repeat=4):
        wd=''.join(t)
        if wd[1:3] in order:
            e = base[wd[0]]*base[wd[1]]*base[wd[2]]*base[wd[3]]*n
            out.append((wd, cnt[wd]/e, cnt[wd], e))
    return sorted(out, key=lambda x:-x[1])
