def score_hairpin(s1, s2):
    # s1, s2 equal length; allow wobble (G-T) - score 2 for G-C, 2 for A-T, 1 for G-T
    sc = 0
    for a, b in zip(s1, s2):
        pair = (a, b)
        if (a,b) in {('G','C'),('C','G'),('A','T'),('T','A')}:
            sc += 3
        elif (a,b) in {('G','T'),('T','G')}:
            sc += 2
    return sc

best = []
for i in range(n - 60):
    for stem in (8, 9, 10, 11, 12):
        s1 = seq[i:i+stem]
        s2 = rc(seq[i+stem+5:i+stem+5+stem])
        sc = score_hairpin(s1, s2)
        following = seq[i+stem+5+stem:i+stem+5+stem+15]
        T = following.count('T')
